mapper.select:
SELECT COUNT(*)
FROM kb_user
WHERE created_at >= #{startDate}
AND created_at <= #{endDate}
AND deleted = 0

SELECT user_id AS id, COUNT(*) AS count
FROM kb_operation_log
WHERE created_at >= #{startDate}
AND created_at <= #{endDate}
AND status = 1
GROUP BY user_id
ORDER BY count DESC
LIMIT #{limit}

SELECT COUNT(*)
FROM kb_operation_log
WHERE user_id = #{userId}
AND created_at >= #{startDate}
AND created_at <= #{endDate}

SELECT COUNT(*)
FROM kb_comment
WHERE user_id = #{userId}

SELECT COUNT(*)
FROM kb_view_history
WHERE user_id = #{userId}
AND created_at >= #{startDate}
AND created_at <= #{endDate}
